CREATE TABLE public.newsletter_subscribers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK(length(email) <= 255), consent_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.newsletter_subscribers TO service_role; GRANT SELECT ON public.newsletter_subscribers TO authenticated; ALTER TABLE public.newsletter_subscribers ENABLE ROW LEVEL SECURITY; CREATE POLICY newsletter_staff_read ON public.newsletter_subscribers FOR SELECT TO authenticated USING(public.has_role(auth.uid(), 'admin')); CREATE TABLE public.bot_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), answer_hash text NOT NULL, expires_at timestamptz NOT NULL, used boolean NOT NULL DEFAULT false); GRANT ALL ON public.bot_challenges TO service_role; ALTER TABLE public.bot_challenges ENABLE ROW LEVEL SECURITY;